const body = $input.item.json.body || $input.item.json;
const leadId = body.lead_id || 'LEAD-001';
const ctx = body.context || {};
const leadName = ctx.lead_name || ctx.name || 'Valued Prospect';
const company = ctx.company || 'Enterprise Partner';
const source = ctx.source || 'inbound_enterprise';
const notes = ctx.notes || '';

// Qualification logic
const isEnterprise = source.includes('enterprise') || notes.toLowerCase().includes('500 seat') || notes.toLowerCase().includes('enterprise');
const score = isEnterprise ? 88 : 70;
const tier = isEnterprise ? 'TIER_1_ENTERPRISE' : 'TIER_2_GROWTH';
const qualificationStatus = 'qualified';
const rationale = isEnterprise ? 'High-value enterprise prospect with 500+ seat potential' : 'Active commercial interest with growth potential';

const subject = `Tailored Enterprise Solution for ${company}`;
const message = `Hello ${leadName},\n\nThank you for reaching out regarding ${company}'s enterprise expansion. We have analyzed your requirements and prepared a tailored commercial proposal.\n\nKey Highlights:\n- Dedicated account architecture\n- Scalable enterprise tiering\n- Seamless AgentX autonomous workflow deployment\n\nWe look forward to discussing next milestones.\n\nBest regards,\nAgentX Commercial Team`;

return [{
  json: {
    success: true,
    workflow: 'sales_process_lead',
    task_id: body.task_id,
    lead_id: leadId,
    lead_status: qualificationStatus,
    qualification: {
      score: score,
      tier: tier,
      status: qualificationStatus,
      rationale: rationale
    },
    actions: [
      'Lead context retrieved and validated',
      `Commercial qualification evaluated (Score: ${score}, ${tier})`,
      'Lead status updated to QUALIFIED',
      'Personalized outreach proposal prepared'
    ],
    follow_up: {
      prepared: true,
      recipient_name: leadName,
      recipient_email: ctx.email || 'prospect@example.com',
      subject: subject,
      message: message
    },
    timestamp: new Date().toISOString()
  }
}];
